{"command": "cd /tmp/sv-dafc0c9304304745b151aa0f82af4f41/symbols

# Even though it's stripped, we can use the dynamic symbol table
# Try using nm -D or objdump to get dynamic symbols and resolve addresses
# Addresses from the tombstone for libmonosgen: 0x222098, 0x222234, 0x19bac0, 0x19bc14

# Use addr2line (won't work for stripped) but let's try nm -D for dynamic symbols
nm -D libmonosgen-2.0.so 2>/dev/null | head -5

# Better: use objdump to find which function each address falls in
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo "=== $addr ==="
  # Find the function containing this address using dynamic symbols
  nm -D --defined-only libmonosgen-2.0.so 2>/dev/null | awk -v target="$addr" '
    BEGIN { target_dec = strtonum(target) }
    /^[0-9a-f]+ [TtWw]/ {
      addr_dec = strtonum("0x" $1)
      if (addr_dec <= target_dec) {
        best_name = $3
        best_addr = addr_dec
      }
    }
    END { if (best_name != "") printf "  %s+0x%x\n", best_name, target_dec - best_addr }
  '
done", "description": "Resolve addresses using dynamic symbols"}
